<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';require_role(['customer']);$s=$pdo->prepare("SELECT p.*,b.bill_number FROM payments p JOIN bills b ON b.id=p.bill_id WHERE p.customer_id=? ORDER BY p.created_at DESC");$s->execute([current_user()['customer_id']]);$rows=$s->fetchAll();$pageTitle='My payments';require 'includes/header.php';?>
<div class="panel"><h3>My payment history</h3><table><thead><tr><th>Receipt</th><th>Bill</th><th>Amount</th><th>Method</th><th>Reference</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>PAY-<?=str_pad((string)$r['id'],6,'0',STR_PAD_LEFT)?></td><td><?=e($r['bill_number'])?></td><td><?=money($r['amount'])?></td><td><?=e(ucfirst($r['method']))?></td><td><?=e($r['reference']??'—')?></td><td><?=e($r['payment_date'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">No payments recorded.</td></tr><?php endif;?></tbody></table></div><?php require 'includes/footer.php';?>
